    async modifierInstitution(id) { const nom = document.getElementById('mod-inst-nom-profil')?.value?.trim(); const adresse = document.getElementById('mod-inst-adresse-profil')?.value?.trim(); const telephone = document.getElementById('mod-inst-tel-profil')?.value?.trim(); const email = document.getElementById('mod-inst-email-profil')?.value?.trim(); const regime = document.getElementById('mod-inst-regime-profil')?.value; const logoFile = document.getElementById('mod-inst-logo-profil')?.files[0]; try { const formData = new FormData(); if (nom) formData.append('nom', nom); if (adresse) formData.append('adresse', adresse); if (telephone) formData.append('telephone', telephone); if (email) formData.append('email', email); if (regime) formData.append('regime', regime); if (logoFile) formData.append('logo', logoFile); const r = await fetch(`${API_URL}/classes/institution/${id}`, { method: 'PUT', headers: { 'Authorization': `Bearer ${getToken()}` }, body: formData }); const data = await r.json(); if (data.success) { document.getElementById('modal-modif-inst-profil')?.remove(); if (regime) setRegime(regime); await updateHeaderInfo(); await this.render(); } else this.ouvrirAlert('Erreur', data.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
    ouvrirModalAjouterNiveau() { const existants = this.institutions.map(i => i.niveau); const disponibles = [{v:'maternelle',l:'Maternelle',i:'child'},{v:'primaire',l:'Primaire',i:'child-reaching'},{v:'secondaire',l:'Secondaire',i:'user-graduate'}].filter(d => !existants.includes(d.v)); if (!disponibles.length) { this.ouvrirAlert('Info', 'Tous les niveaux sont déjà ajoutés.', 'info'); return; } const overlay = document.createElement('div'); overlay.className = 'modal-overlay'; overlay.id = 'modal-ajout-niveau-profil'; overlay.onclick = e => { if (e.target === overlay) overlay.remove(); }; const itemsHTML = disponibles.map(d => `<div class="ui-card card-hoverable ajout-niv-item-profil" data-niveau="${d.v}"><div style="padding:0.8rem 1rem;display:flex;align-items:center;gap:0.6rem"><i class="fas fa-${d.i}" style="color:var(--primary);font-size:1.2rem;flex-shrink:0"></i><span style="font-size:0.9rem;font-weight:500">${d.l}</span></div></div>`).join(''); overlay.innerHTML = `<div class="modal" style="max-width:420px;max-height:80vh;display:flex;flex-direction:column" onclick="event.stopPropagation()"><div class="modal-header"><h3><i class="fas fa-layer-group"></i> Ajouter un niveau</h3><button class="modal-close" id="close-ajout-niveau-profil"><i class="fas fa-times"></i></button></div><div class="modal-body" style="flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:0.5rem;padding-bottom:0.5rem">${itemsHTML}</div></div>`; document.body.appendChild(overlay); overlay.querySelector('#close-ajout-niveau-profil').onclick = () => overlay.remove(); overlay.querySelectorAll('.ajout-niv-item-profil').forEach(el => { el.addEventListener('click', () => this.ajouterNiveau(el.dataset.niveau)); }); }
    async ajouterNiveau(niveau) { try { const r = await apiPost('/classes/institution', { nom: this.institutions[0]?.nom || 'Complexe Scolaire Avenir', niveau }); if (r.success) { document.getElementById('modal-ajout-niveau-profil')?.remove(); await this.render(); } else this.ouvrirAlert('Erreur', r.message||'Échec','error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
