    async enregistrerProfesseurInst() { const nom = document.getElementById('prof-inst-nom')?.value?.trim(), prenom = document.getElementById('prof-inst-prenom')?.value?.trim(), date_naissance = document.getElementById('prof-inst-date')?.value, genre = document.getElementById('prof-inst-genre')?.value, telephone = document.getElementById('prof-inst-tel')?.value?.trim() || null, email = document.getElementById('prof-inst-email')?.value?.trim() || null, date_embauche = document.getElementById('prof-inst-embauche')?.value; if (!nom || !prenom || !date_naissance || !date_embauche) { this.ouvrirAlert('Champs requis', 'Remplissez tous les champs obligatoires.', 'warning'); return; } try { const r = await API.createProfesseur({ nom, prenom, date_naissance, genre, telephone, email, date_embauche }); if (r.success) { document.getElementById('modal-ajout-prof-inst')?.remove(); this.ouvrirAlert('Succès', 'Professeur créé !', 'success'); await this.render(); } else this.ouvrirAlert('Erreur', r.message || 'Échec', 'error'); } catch(e) { this.ouvrirAlert('Erreur', e.message, 'error'); } }
